import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.lstrip("\ufeff")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.splitlines()
    data_start = 0
    for i, line in enumerate(lines):
        if line.strip():
            data_start = i
            break
    else:
        return {"columns": [], "rows": []}

    sample = "\n".join(lines[data_start:data_start + min(20, len(lines) - data_start)])
    try:
        dialect = csv.Sniffer().sniff(sample, delimiters=[",", ";", "\t", "|"])
    except Exception:
        dialect = csv.get_dialect("excel")
        dialect.delimiter = ","
        dialect.quotechar = '"'
        dialect.doublequote = True
        dialect.skipinitialspace = False
        dialect.lineterminator = "\n"
        dialect.quoting = csv.QUOTE_MINIMAL

    dialect.delimiter = ","
    dialect.quotechar = '"'
    dialect.doublequote = True
    dialect.skipinitialspace = False
    dialect.strict = False

    def parse_with_csv(s: str) -> List[List[str]]:
        reader = csv.reader(io.StringIO(s), dialect=dialect)
        rows = []
        for row in reader:
            rows.append([str(v) for v in row])
        return rows

    rows = parse_with_csv(text)

    def normalize_row(row: List[str], width: int) -> List[str]:
        if len(row) < width:
            return row + [""] * (width - len(row))
        if len(row) > width:
            return row[:width - 1] + [",".join(row[width - 1:])]
        return row

    width = 0
    for r in rows[: min(len(rows), 10)]:
        width = max(width, len(r))
    if width == 0:
        return {"columns": [], "rows": []}

    rows = [normalize_row(r, width) for r in rows]

    header = rows[0]
    data_rows = rows[1:] if len(rows) > 1 else []

    if len(header) == 1 and len(data_rows) > 0 and any(len(r) > 1 for r in data_rows):
        header = [header[0]] + [f"column_{i}" for i in range(2, max(len(r) for r in data_rows) + 1)]
        width = len(header)
        data_rows = [normalize_row(r, width) for r in data_rows]
    else:
        width = len(header)
        data_rows = [normalize_row(r, width) for r in data_rows]

    return {"columns": header, "rows": data_rows}
